import tools.jackson.databind.json.JsonMapper;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
class V22HouseholdIntegrationTests {
 static final EmbeddedPostgres PG;
 static{try{PG=EmbeddedPostgres.builder().setPort(0).start();}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->PG.getJdbcUrl("postgres","postgres"));r.add("spring.datasource.username",()->"postgres");r.add("spring.datasource.password",()->"postgres");r.add("pawday.auth.secret-key",()->"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=");r.add("management.health.redis.enabled",()->false);r.add("management.health.rabbit.enabled",()->false);r.add("pawday.outbox.workers-enabled",()->false);r.add("pawday.outbox.consumer-enabled",()->false);r.add("pawday.search.enabled",()->false);r.add("pawday.storage.cleanup-enabled",()->false);}
 @Autowired JdbcTemplate db;@Autowired Crypto crypto;@Autowired Clock clock;@LocalServerPort int port;
 final JsonMapper json=JsonMapper.builder().build();final HttpClient http=HttpClient.newHttpClient();
 static final List<Map<String,Object>> SAMPLES=new CopyOnWriteArrayList<>();
 record Identity(String token,UUID user){} record Response(int status,JsonNode body){JsonNode data(){return body.get("data");}String id(){return data().get("id").asString();}}
 Identity owner,member,other;String admin;UUID pet;
 String key(){return UUID.randomUUID().toString();}
 Identity identity(String realm){UUID u=UUID.randomUUID(),p=UUID.randomUUID();if(realm.equals("CONSUMER")){db.update("INSERT INTO app_user(id,status) VALUES (?,'ACTIVE')",u);db.update("INSERT INTO identity_principal(id,realm,user_id) VALUES (?,'CONSUMER',?)",p,u);}else db.update("INSERT INTO identity_principal(id,realm,login_name,password_hash) VALUES (?,?,?,'TEST-ONLY')",p,realm,key());String token=crypto.token();db.update("INSERT INTO auth_session(id,principal_id,access_token_hash,device_id,expires_at,refresh_expires_at,created_at) VALUES (?,?,?,'HOUSEHOLD-IT',?,?,?)",UUID.randomUUID(),p,crypto.hash(token),Timestamp.from(clock.instant().plusSeconds(900)),Timestamp.from(clock.instant().plusSeconds(2592000)),Timestamp.from(clock.instant()));return new Identity(token,u);}
 @BeforeEach void setup(){owner=identity("CONSUMER");member=identity("CONSUMER");other=identity("CONSUMER");admin=identity("ADMIN").token();pet=UUID.randomUUID();db.update("INSERT INTO pets(id,owner_user_id,name,species_id,sex,neutered_status) VALUES (?,?,'TEST-ONLY shared pet','10000000-0000-4000-8000-000000000001','UNKNOWN','UNKNOWN')",pet,owner.user());}
 String path(){return "/consumer/household/pets/"+pet;}
 Response req(String method,String path,Object b,String who,String k,Long v){try{var q=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1"+path)).timeout(Duration.ofSeconds(25));if(who!=null)q.header("Authorization","Bearer "+who);if(k!=null)q.header("Idempotency-Key",k);if(v!=null)q.header("If-Match","\""+v+"\"");if(b==null)q.method(method,HttpRequest.BodyPublishers.noBody());else q.header("Content-Type","application/json").method(method,HttpRequest.BodyPublishers.ofString(json.writeValueAsString(b)));var r=http.send(q.build(),HttpResponse.BodyHandlers.ofString());var body=json.readTree(r.body());if(path.startsWith("/consumer/household")){var safe=json.readTree(r.body());if(safe.has("data")&&safe.get("data").isObject()&&safe.get("data").has("invite_token"))((tools.jackson.databind.node.ObjectNode)safe.get("data")).put("invite_token","A".repeat(43));SAMPLES.add(Map.of("method",method.toLowerCase(),"path",path,"status",r.statusCode(),"response",safe));}return new Response(r.statusCode(),body);}catch(Exception e){throw new AssertionError(e);}}
 Response read(String who){return req("GET",path(),null,who,null,null);}
 Response invite(String role){return req("POST",path()+"/invites",Map.of("role",role),owner.token(),key(),null);}
 Response accept(Response invitation,Identity who,String k){return req("POST","/consumer/household/accept",Map.of("invite_token",invitation.data().get("invite_token").asString()),who.token(),k,null);}
 void join(String role){var i=invite(role);assertEquals(201,i.status(),i.body().toString());assertEquals(200,accept(i,member,key()).status());}
 Map<String,Object> task(){return Map.of("title","TEST-ONLY feed","due_on",LocalDate.now(ZoneId.of("Asia/Shanghai")).toString());}
 Map<String,Object> entry(){return Map.of("kind","NOTE","note","TEST-ONLY observation","recorded_on",LocalDate.now(ZoneId.of("Asia/Shanghai")).toString());}
 @Test void paginatedPetsDoNotSkipAndMemberCapDoesNotConsumeInvite(){
  UUID second=UUID.randomUUID();db.update("INSERT INTO pets(id,owner_user_id,name,species_id,sex,neutered_status) VALUES (?,?,'TEST_ONLY_PAGE','10000000-0000-4000-8000-000000000001','UNKNOWN','UNKNOWN')",second,owner.user());
  var page=req("GET","/consumer/household/pets?limit=1",null,owner.token(),null,null);assertEquals(200,page.status());assertTrue(page.body().get("page").get("has_more").asBoolean());String cursor=page.body().get("page").get("next_cursor").asString();var next=req("GET","/consumer/household/pets?limit=1&cursor="+cursor,null,owner.token(),null,null);assertEquals(200,next.status());assertFalse(next.body().get("page").get("has_more").asBoolean());assertNotEquals(page.data().get(0).get("id").asString(),next.data().get(0).get("id").asString());assertEquals(400,req("GET","/consumer/household/pets?limit=101",null,owner.token(),null,null).status());
  for(int n=0;n<20;n++){var u=identity("CONSUMER");db.update("INSERT INTO pet_share_members(pet_id,user_id,role,status) VALUES (?,?,'VIEWER','ACTIVE')",pet,u.user());}
  var i=invite("VIEWER");assertEquals(409,accept(i,member,key()).status());assertEquals("PENDING",db.queryForObject("SELECT status FROM pet_share_invites WHERE id=?",String.class,UUID.fromString(i.id())));
  for(int n=0;n<100;n++){UUID u=UUID.randomUUID();db.update("INSERT INTO app_user(id,status) VALUES (?,'ACTIVE')",u);db.update("INSERT INTO pet_share_members(pet_id,user_id,role,status,ended_at) VALUES (?, ?,'VIEWER','LEFT',clock_timestamp())",pet,u);}
  assertEquals(20,read(owner.token()).data().get("members").valueStream().filter(m->m.get("status").asString().equals("ACTIVE")).count());
 }
 @AfterAll static void close()throws Exception{Files.writeString(Path.of("target/v22-contract-samples.json"),JsonMapper.builder().build().writeValueAsString(SAMPLES));PG.close();}
 @Test void scopeRolesAndUnrelatedOwnerBoundaries(){assertEquals(401,read(null).status());assertEquals(403,read(admin).status());assertEquals(404,read(other.token()).status());join("VIEWER");var p=read(member.token());assertEquals(200,p.status());assertEquals("VIEWER",p.data().get("pet").get("share_role").asString());assertFalse(p.data().get("pet").has("photo_asset_id"));assertEquals(403,req("POST",path()+"/tasks",task(),member.token(),key(),null).status());assertEquals(403,req("POST",path()+"/entries",entry(),member.token(),key(),null).status());assertEquals(404,req("POST",path()+"/invites",Map.of("role","CAREGIVER"),member.token(),key(),null).status());assertEquals(404,req("GET","/consumer/pets/"+pet,null,member.token(),null,null).status());assertEquals(404,req("PATCH","/consumer/pets/"+pet,Map.of("name","TEST override"),member.token(),key(),0L).status());assertEquals(404,req("DELETE","/consumer/pets/"+pet,null,member.token(),key(),0L).status());assertEquals(404,req("GET","/consumer/pets/"+pet+"/weight-records",null,member.token(),null,null).status());assertEquals(404,req("GET","/consumer/pets/"+pet+"/food",null,member.token(),null,null).status());assertTrue(req("GET","/consumer/household/pets",null,member.token(),null,null).data().valueStream().anyMatch(x->x.get("id").asString().equals(pet.toString())));}
 @Test void invitesAreSingleUseEncryptedAndIdempotent(){String k=key();var i=req("POST",path()+"/invites",Map.of("role","CAREGIVER"),owner.token(),k,null);assertEquals(201,i.status());var repeated=req("POST",path()+"/invites",Map.of("role","CAREGIVER"),owner.token(),k,null);assertEquals(i.data().get("invite_token").asString(),repeated.data().get("invite_token").asString());String stored=db.queryForObject("SELECT result_json::text FROM identity_command WHERE action=?",String.class,"household.invite:"+pet);assertFalse(stored.contains(i.data().get("invite_token").asString()));assertTrue(stored.contains("token_ciphertext"));assertEquals(409,accept(i,owner,key()).status());String ak=key();assertEquals(200,accept(i,member,ak).status());assertEquals(200,accept(i,member,ak).status());assertEquals(404,accept(i,other,key()).status());assertEquals(409,req("POST",path()+"/invites",Map.of("role","CAREGIVER"),owner.token(),k,null).status());String audit=db.queryForObject("SELECT string_agg(after_json::text,'') FROM audit_event WHERE object_id=?",String.class,pet.toString());assertFalse(audit.contains(i.data().get("invite_token").asString()));}
 @Test void concurrentAcceptHasExactlyOneWinner()throws Exception{var i=invite("CAREGIVER");try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->accept(i,member,key()));var b=pool.submit(()->accept(i,other,key()));var statuses=List.of(a.get().status(),b.get().status());assertTrue(statuses.contains(200)&&statuses.contains(404));}assertEquals(1,db.queryForObject("SELECT count(*) FROM pet_share_members WHERE pet_id=?",Integer.class,pet));}
 @Test void expiredRevokedAndInvalidInvitationsCannotGrant(){var i=invite("VIEWER");db.update("UPDATE pet_share_invites SET created_at=clock_timestamp()-interval '2 days',expires_at=clock_timestamp()-interval '1 day' WHERE id=?",UUID.fromString(i.id()));assertEquals(404,accept(i,member,key()).status());assertEquals("EXPIRED",read(owner.token()).data().get("invites").get(0).get("status").asString());var j=invite("VIEWER");assertEquals(200,req("POST",path()+"/invites/"+j.id()+"/revoke",null,owner.token(),key(),null).status());assertEquals(404,accept(j,member,key()).status());assertEquals(400,req("POST","/consumer/household/accept",Map.of("invite_token","bad"),member.token(),key(),null).status());assertEquals(404,req("POST","/consumer/household/accept",Map.of("invite_token","A".repeat(43)),member.token(),key(),null).status());}
 @Test void revokeIsImmediateIncludingCachedWritesAndUnusedInvites(){var i=invite("CAREGIVER");String ak=key();assertEquals(200,accept(i,member,ak).status());String ek=key();assertEquals(201,req("POST",path()+"/entries",entry(),member.token(),ek,null).status());var unused=invite("VIEWER");String url=path()+"/members/"+member.user()+"/revoke";assertEquals(409,req("POST",url,null,owner.token(),key(),5L).status());assertEquals(200,req("POST",url,null,owner.token(),key(),0L).status());assertEquals(404,read(member.token()).status());assertEquals(404,req("POST",path()+"/entries",entry(),member.token(),ek,null).status());assertEquals(404,accept(i,member,ak).status());assertEquals(404,accept(unused,other,key()).status());assertEquals(1,db.queryForObject("SELECT count(*) FROM pet_care_entries WHERE pet_id=?",Integer.class,pet));}
 @Test void leaveRequiresOwnVersionAndNewInviteCanRejoin(){join("VIEWER");assertEquals(400,req("POST",path()+"/leave",null,member.token(),key(),null).status());assertEquals(200,req("POST",path()+"/leave",null,member.token(),key(),0L).status());assertEquals(404,read(member.token()).status());assertEquals(200,accept(invite("CAREGIVER"),member,key()).status());assertEquals("CAREGIVER",read(member.token()).data().get("pet").get("share_role").asString());assertEquals(2,db.queryForObject("SELECT version FROM pet_share_members WHERE pet_id=? AND user_id=?",Integer.class,pet,member.user()));}
 @Test void taskConflictTerminalAndAppendOnlyRecords()throws Exception{join("CAREGIVER");String k=key();var t=req("POST",path()+"/tasks",task(),owner.token(),k,null);assertEquals(201,t.status());assertEquals(t.id(),req("POST",path()+"/tasks",task(),owner.token(),k,null).id());String url=path()+"/tasks/"+t.id()+"/finish";assertEquals(403,req("POST",url,Map.of("status","CANCELLED"),member.token(),key(),0L).status());try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->req("POST",url,Map.of("status","DONE"),member.token(),key(),0L));var b=pool.submit(()->req("POST",url,Map.of("status","DONE"),owner.token(),key(),0L));var codes=List.of(a.get().status(),b.get().status());assertTrue(codes.contains(200)&&codes.contains(409));}assertEquals(409,req("POST",url,Map.of("status","CANCELLED"),owner.token(),key(),1L).status());String ek=key();var e=req("POST",path()+"/entries",entry(),member.token(),ek,null);assertEquals(201,e.status());assertEquals(e.id(),req("POST",path()+"/entries",entry(),member.token(),ek,null).id());assertEquals(member.user().toString(),e.data().get("actor_user_id").asString());assertThrows(RuntimeException.class,()->db.update("UPDATE pet_care_entries SET note='overwrite' WHERE pet_id=?",pet));assertThrows(RuntimeException.class,()->db.update("DELETE FROM pet_care_entries WHERE pet_id=?",pet));assertThrows(RuntimeException.class,()->db.execute("TRUNCATE pet_care_entries"));assertThrows(RuntimeException.class,()->db.execute("TRUNCATE pet_care_tasks"));assertThrows(RuntimeException.class,()->db.update("UPDATE pet_care_tasks SET status='OPEN',version=version+1,completed_by=NULL,ended_at=NULL WHERE id=?",UUID.fromString(t.id())));}
 @Test void auditFailureRollsBackInvitationsAndCommands(){db.execute("CREATE FUNCTION v22_fail_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='household.invite' THEN RAISE EXCEPTION 'TEST_ONLY'; END IF; RETURN NEW; END $$");db.execute("CREATE TRIGGER v22_fail_audit BEFORE INSERT ON audit_event FOR EACH ROW EXECUTE FUNCTION v22_fail_audit()");try{assertEquals(503,invite("VIEWER").status());assertEquals(0,db.queryForObject("SELECT count(*) FROM pet_share_invites WHERE pet_id=?",Integer.class,pet));assertEquals(0,db.queryForObject("SELECT count(*) FROM identity_command WHERE action=?",Integer.class,"household.invite:"+pet));}finally{db.execute("DROP TRIGGER v22_fail_audit ON audit_event");db.execute("DROP FUNCTION v22_fail_audit()");}}
 @Test void validationAbuseAndDeletedPetFailClosed(){assertEquals(400,req("POST",path()+"/invites",Map.of("role","OWNER"),owner.token(),key(),null).status());assertEquals(400,req("POST",path()+"/tasks",task(),owner.token(),null,null).status());assertEquals(400,req("POST",path()+"/tasks",Map.of("title","TEST","due_on","2099-01-01"),owner.token(),key(),null).status());for(int i=0;i<5;i++)assertEquals(201,invite("VIEWER").status());assertEquals(409,invite("VIEWER").status());for(int i=0;i<10;i++)assertEquals(404,req("POST","/consumer/household/accept",Map.of("invite_token","A".repeat(43)),member.token(),key(),null).status());assertEquals(429,req("POST","/consumer/household/accept",Map.of("invite_token","A".repeat(43)),member.token(),key(),null).status());db.update("UPDATE pets SET status='DELETED' WHERE id=?",pet);assertEquals(404,read(owner.token()).status());}
}
